"use client";
import type { ButtonHTMLAttributes, ReactNode } from "react";
import { useEffect, useId, useRef, useState } from "react";
import "./hold-button.css";

/** Press and hold (pointer, Space, or Enter) to confirm a consequential action. */
export function HoldButton({
  children,
  onConfirm,
  duration = 1200,
  confirmedLabel = "Confirmed",
  className = "",
  type = "button",
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement> & {
  onConfirm?: () => void;
  duration?: number;
  confirmedLabel?: ReactNode;
}) {
  const hint = useId();
  const [progress, setProgress] = useState(0);
  const [done, setDone] = useState(false);
  const run = useRef({ holding: false, value: 0, last: 0, frame: 0, reset: 0 });
  const confirm = useRef(onConfirm);
  confirm.current = onConfirm;
  useEffect(() => {
    const state = run.current;
    return () => {
      cancelAnimationFrame(state.frame);
      clearTimeout(state.reset);
    };
  }, []);
  const loop = (now: number) => {
    const state = run.current;
    const elapsed = now - state.last;
    state.last = now;
    // Filling takes `duration`; releasing drains three times faster.
    state.value = Math.max(
      0,
      Math.min(1, state.value + (state.holding ? 1 : -3) * (elapsed / duration)),
    );
    setProgress(state.value);
    if (state.value >= 1) {
      state.holding = false;
      setDone(true);
      confirm.current?.();
      state.reset = window.setTimeout(() => {
        state.value = 0;
        setProgress(0);
        setDone(false);
      }, 1600);
      return;
    }
    if (state.holding || state.value > 0)
      state.frame = requestAnimationFrame(loop);
  };
  const begin = () => {
    const state = run.current;
    if (props.disabled || done || state.holding) return;
    state.holding = true;
    cancelAnimationFrame(state.frame);
    state.last = performance.now();
    state.frame = requestAnimationFrame(loop);
  };
  const end = () => {
    run.current.holding = false;
  };
  return (
    <button
      {...props}
      type={type}
      aria-describedby={hint}
      data-done={done || undefined}
      className={`forme-hold ${className}`}
      style={{ ...props.style, ["--forme-hold" as string]: progress }}
      onPointerDown={(e) => {
        if (e.button !== 0) return;
        e.currentTarget.setPointerCapture(e.pointerId);
        begin();
        props.onPointerDown?.(e);
      }}
      onPointerUp={(e) => {
        end();
        props.onPointerUp?.(e);
      }}
      onPointerCancel={end}
      onLostPointerCapture={end}
      onKeyDown={(e) => {
        if (e.key === " " || e.key === "Enter") {
          e.preventDefault();
          if (!e.repeat) begin();
        }
        props.onKeyDown?.(e);
      }}
      onKeyUp={(e) => {
        if (e.key === " " || e.key === "Enter") end();
        props.onKeyUp?.(e);
      }}
      onBlur={(e) => {
        end();
        props.onBlur?.(e);
      }}
      onContextMenu={(e) => e.preventDefault()}
    >
      <span className="forme-hold-label">{done ? confirmedLabel : children}</span>
      {/* The fill carries an inverted copy of the label, revealed as the hold charges. */}
      <span className="forme-hold-fill" aria-hidden="true">
        <span className="forme-hold-label">{done ? confirmedLabel : children}</span>
      </span>
      <span id={hint} className="forme-hold-sr">
        Press and hold to confirm
      </span>
      <span className="forme-hold-sr" role="status">
        {done ? confirmedLabel : ""}
      </span>
    </button>
  );
}

.forme-hold {
  --forme-hold-bg: #151517;
  --forme-hold-ink: #ededf0;
  --forme-hold-fill: #f4f4f5;
  --forme-hold-fill-ink: #09090b;
  position: relative;
  display: inline-grid;
  height: 48px;
  padding: 0 26px;
  border: 1px solid #ffffff1a;
  border-radius: 999px;
  background: var(--forme-hold-bg);
  box-shadow:
    inset 0 1px 0 #ffffff0f,
    0 1px 2px #0006;
  color: var(--forme-hold-ink);
  font: inherit;
  font-size: 15px;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  touch-action: manipulation;
  transition:
    transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1),
    border-color 0.2s;
}
.forme-hold > .forme-hold-label,
.forme-hold-fill {
  grid-area: 1 / 1;
}
.forme-hold-label {
  display: grid;
  place-items: center;
  white-space: nowrap;
}
.forme-hold-fill {
  display: grid;
  margin: -1px -27px;
  padding: 0 26px;
  border-radius: inherit;
  background: var(--forme-hold-fill);
  color: var(--forme-hold-fill-ink);
  clip-path: inset(0 calc(100% - var(--forme-hold, 0) * 100%) 0 0);
}
.forme-hold:hover {
  border-color: #ffffff33;
}
.forme-hold:active {
  transform: scale(0.98);
}
.forme-hold:focus-visible {
  outline: 2px solid #f4f4f5;
  outline-offset: 3px;
}
.forme-hold:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.forme-hold-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (prefers-reduced-motion: reduce) {
  /* The fill still tracks the hold: it is progress information, not decoration. */
  .forme-hold {
    transition: none;
  }
  .forme-hold:active {
    transform: none;
  }
}
